bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
source_sha=645fbf5a202da1510a24d979f02254c8d9c30ad0
stage=/home/gace/.local/share/gace-create-videobot/safe-unpurchased-archive-645fbf5a
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
image="$(docker inspect "$cid" --format '{{.Config.Image}}')"
case "$image" in
 create-videobot:newpost-slim-fcb0676|create-videobot:newpost-reconcile-3efec7) ;;
 *) echo VIDEO_ARCHIVE_LIVE_IMAGE_CHANGED; exit 62;;
esac
test "$(docker inspect "$cid" --format '{{.Image}}')" = "$(docker image inspect "$image" --format '{{.Id}}')" || exit 63
git fetch origin refs/heads/fix/archive-unpurchased-duplicate-video-drafts-20261124 >/dev/null 2>&1 || exit 64
test "$(git rev-parse FETCH_HEAD)" = "$source_sha" || exit 65
mkdir -p "$stage"
git show "$source_sha:src/operations/archiveUnpurchasedSameTitleDrafts.mjs" > "$stage/archiveUnpurchasedSameTitleDrafts.mjs"
docker run --rm --network none --entrypoint node -v "$stage/archiveUnpurchasedSameTitleDrafts.mjs:/opt/videobot/src/operations/archiveUnpurchasedSameTitleDrafts.mjs:ro" "$image" --check /opt/videobot/src/operations/archiveUnpurchasedSameTitleDrafts.mjs || exit 66
envlines="$(docker inspect "$cid" --format '{{range .Config.Env}}{{println .}}{{end}}')"
dbhost="$(printf '%s\n' "$envlines" | sed -n 's/^VIDEOBOT_DB_HOST=//p' | head -n1)"
dbuser="$(printf '%s\n' "$envlines" | sed -n 's/^VIDEOBOT_DB_USER=//p' | head -n1)"
dbname="$(printf '%s\n' "$envlines" | sed -n 's/^VIDEOBOT_DB_NAME=//p' | head -n1)"
dbmount="$(docker inspect "$cid" --format '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_db_password"}}{{.Source}}{{end}}{{end}}')"
dbnet="$(docker inspect "$cid" --format '{{range $name, $network := .NetworkSettings.Networks}}{{println $name}}{{end}}' | head -n1)"
test -n "$dbhost" && test -n "$dbuser" && test "$dbname" = videobot && test -f "$dbmount" && test -n "$dbnet" || exit 67
docker run --rm --network "$dbnet" -w /opt/videobot --entrypoint node \
 -e VIDEOBOT_DB_HOST="$dbhost" -e VIDEOBOT_DB_USER="$dbuser" -e VIDEOBOT_DB_NAME="$dbname" \
 -v "$dbmount:/run/secrets/videobot_db_password:ro" \
 -v "$stage/archiveUnpurchasedSameTitleDrafts.mjs:/opt/videobot/src/operations/archiveUnpurchasedSameTitleDrafts.mjs:ro" \
 "$image" --input-type=module -e "
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {archiveUnpurchasedSameTitleDrafts} from './src/operations/archiveUnpurchasedSameTitleDrafts.mjs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
try{
 const x=await archiveUnpurchasedSameTitleDrafts({pool,apply:false});
 if(x.eligible===0)process.exitCode=72;
 else if(x.eligible>0)console.log('VIDEO_UNPURCHASED_PRIVATE_DRAFTS_EXIST=PASS');
 else process.exitCode=73;
}catch(e){
 const m=String(e?.message||'');
 process.exitCode=m.includes('NO_VERIFIED_BUYER')?74:m.includes('GROUP_UNVERIFIED')?75:76;
}finally{await pool.end()}
"
